// Merge both query results (drafts + stuck items) into a single Telegram
// alert. Keep the two buckets clearly labelled so on-call knows whether
// they need to nudge editors (sheet queue) or requeue fan-out items (DB).
const drafts = $('Overdue drafts').all().map(x => x.json);
const items  = $('Stuck fan-out items').all().map(x => x.json);
if (!drafts.length && !items.length) return [];

const fmtDraft = d => `• [${d.platform}] ${d.id} (${Math.floor((Date.now() - new Date(d.created_at).getTime())/60000)}m)`;
const fmtItem  = i => `• [${i.status}] ${i.id} — ${(i.title || '').slice(0,60)} (${Math.floor(i.stuck_seconds/60)}m)`;

const parts = [];
if (drafts.length) {
  parts.push(`*Editorial SLA breach — ${drafts.length} draft(s) > 2h*`);
  parts.push(drafts.map(fmtDraft).join('\n'));
}
if (items.length) {
  parts.push(`*Fan-out watchdog — ${items.length} item(s) stuck > 30m*`);
  parts.push('Requeue SQL: `UPDATE content.items SET status=\'enriched\', locked_at=NULL WHERE id=...`');
  parts.push(items.map(fmtItem).join('\n'));
}

return [{ json: {
  draftCount: drafts.length,
  stuckCount: items.length,
  text: parts.join('\n\n').slice(0, 3500)
}}];
